import { createRequire } from "node:module";
import path from "node:path";
import {
  cloudflareTest,
  readD1Migrations,
} from "@cloudflare/vitest-pool-workers";
import { defineConfig } from "vitest/config";

export default defineConfig(async () => {
  // The admin Worker's D1 migrations, generated by drizzle-kit.
  const migrations = await readD1Migrations(
    path.join(import.meta.dirname, "../../apps/admin/migrations"),
  );
  return {
    plugins: [
      cloudflareTest({
        // The main module exports ConfigVersion, for the race tests.
        main: createRequire(import.meta.url).resolve("@edgway/adapters-cf"),
        miniflare: {
          compatibilityDate: "2025-04-14",
          compatibilityFlags: ["nodejs_compat"],
          d1Databases: ["DB"],
          kvNamespaces: ["CONFIG_KV"],
          durableObjects: { CONFIG_VERSION: "ConfigVersion" },
          bindings: { TEST_MIGRATIONS: migrations },
        },
      }),
    ],
    test: {
      include: ["test/**/*.test.ts"],
      setupFiles: ["./test/apply-migrations.ts"],
    },
  };
});
